namespace {String pitchLabel(int pitch){return harmonyPitchClass(pitch%12).upToFirstOccurrenceOf(" /",false,false)+String(pitch/12-1);}}
bool Studio::setHarmonyGuide(const HarmonyGuide& next,uint64_t expected,const String& token){
    if(recording||recorder.isActive()){status="Finish the take before changing the scale guide.";return false;}if(expected!=harmonyGuideRevision){status="Scale settings changed. Reopen the settings.";return false;}auto saved=saveHarmonyGuide(root.getChildFile("data/harmony.json"),next,token);if(saved.failed()){status=saved.getErrorMessage();return false;}harmonyGuide=next;harmonyPresetGuide.reset();++harmonyGuideRevision;++harmonyToolSerial;
    if(noteToolCurrent()&&harmonyToolActive())refreshNoteToolPreview();status="Scale guide: "+harmonyPitchClass(next.root)+" "+harmonyScaleName(next.scale)+". Guide settings are local; notes change only with Apply.";repaint();return true;
}
void Studio::showHarmonySettings(){
    if(recording||recorder.isActive()){status="Finish the take before changing scale settings.";return;}auto guide=activeHarmonyGuide();bool preview=noteToolCurrent()&&harmonyToolActive();auto serial=harmonyToolSerial;auto* dialog=new AlertWindow("Scale guide and key","Choose the tonic and scale. This shades the Piano roll and supplies the scale for harmony tools. Notes, song tuning and project history stay intact. Apply guide saves the local default, including a loaded preset key. Melodic minor uses the ascending form in both directions.",MessageBoxIconType::NoIcon,this);StringArray roots,scales;for(int i=0;i<12;++i)roots.add(harmonyPitchClass(i));for(int i=0;i<harmonyScaleCount;++i)scales.add(harmonyScaleName(i));dialog->addComboBox("root",roots,"Tonic");dialog->getComboBoxComponent("root")->setSelectedItemIndex(guide.root);dialog->addComboBox("scale",scales,"Scale");dialog->getComboBoxComponent("scale")->setSelectedItemIndex(guide.scale);dialog->addComboBox("guide",{"Show scale guide","Hide scale guide"},"Piano-roll shading");dialog->getComboBoxComponent("guide")->setSelectedItemIndex(guide.enabled?0:1);dialog->addButton("Apply guide",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);auto expected=harmonyGuideRevision;auto token=harmonyGuideToken(root.getChildFile("data/harmony.json"));
    dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,expected,token,preview,serial](int choice){if(safe&&choice==1){if(preview&&(!safe->noteToolCurrent()||safe->harmonyToolSerial!=serial)){safe->status="Harmony preview changed. Reopen Scale settings.";return;}safe->setHarmonyGuide({dialog->getComboBoxComponent("root")->getSelectedItemIndex(),dialog->getComboBoxComponent("scale")->getSelectedItemIndex(),dialog->getComboBoxComponent("guide")->getSelectedItemIndex()==0},expected,token);}}),true);
}
bool Studio::harmonyToolActive()const{return noteToolOptions.mode==NoteToolMode::fitScale||noteToolOptions.mode==NoteToolMode::buildChord||noteToolOptions.mode==NoteToolMode::buildProgression;}
bool Studio::harmonyContext(uint64_t expected,uint64_t serial)const{return !recording&&!recorder.isActive()&&harmonyToolActive()&&noteToolCurrent()&&revision==expected&&harmonyToolSerial==serial&&selectedTrack==noteToolTrack&&project.activePattern==noteToolPattern;}
bool Studio::acceptHarmonyChoice(int kind,int value,uint64_t expected,uint64_t serial){
    if(!harmonyContext(expected,serial)){status="Harmony source or settings changed. Reopen the control.";return false;}
    if((kind==0&&(value<0||value>=chordQualityCount))||(kind==1&&(value<0||value>3))||(kind==2&&(value<1||value>3))||(kind==3&&(value<0||value>2))||kind<0||kind>3){status="Invalid harmony choice.";return false;}
    if(kind==0)chordOptions.quality=value;else if(kind==1)chordOptions.inversion=value;else if(kind==2)chordOptions.octaves=value;else scaleFitDirection=(ScaleDirection)value;++harmonyToolSerial;refreshNoteToolPreview();return true;
}
void Studio::showHarmonyChoice(int kind){
    if(!harmonyContext(revision,harmonyToolSerial))return;PopupMenu menu;if(kind==0)for(int i=0;i<chordQualityCount;++i)menu.addItem(i+1,chordQualityName(i),true,chordOptions.quality==i);
    else if(kind==1){const char* names[]={"Root position","First inversion","Second inversion","Third inversion"};for(int i=0;i<4;++i)menu.addItem(i+1,names[i],true,chordOptions.inversion==i);}
    else if(kind==2)for(int i=1;i<=3;++i)menu.addItem(i,String(i)+" octave layer"+(i==1?String():"s"),true,chordOptions.octaves==i);
    else if(kind==3){const char* names[]={"Nearest (ties downward)","Down only","Up only"};for(int i=0;i<3;++i)menu.addItem(i+1,names[i],true,(int)scaleFitDirection==i);}else return;
    auto safe=Component::SafePointer<Studio>(this);auto expected=revision,serial=harmonyToolSerial;menu.showMenuAsync(menuOptions(harmonyChoice,kind),[safe,kind,expected,serial](int result){if(safe&&result>0)safe->acceptHarmonyChoice(kind,kind==2?result:result-1,expected,serial);});
}
bool Studio::acceptHarmonyNumber(int parameter,double value,uint64_t expected,uint64_t serial){
    if(!harmonyContext(expected,serial)||noteToolOptions.mode!=NoteToolMode::buildChord){status="Chord source or settings changed. Reopen the value.";return false;}
    if(!std::isfinite(value)||parameter<0||parameter>3||(parameter==0&&(value<0||value>127||value!=std::floor(value)))||(parameter==1&&(value<0||value>=noteToolLength))||(parameter==2&&(value<.01||value>64))||(parameter==3&&(value<1||value>100))){status="Enter a valid chord pitch, pattern beat, duration or velocity (1-100%).";return false;}
    if(parameter==0)chordOptions.root=(int)value;else if(parameter==1)chordOptions.beat=value;else if(parameter==2)chordOptions.length=value;else chordOptions.velocity=(float)(value/100);++harmonyToolSerial;pianoLow=-1;refreshNoteToolPreview();return true;
}
void Studio::editHarmonyNumber(int parameter){
    if(parameter<0||parameter>3||!harmonyContext(revision,harmonyToolSerial))return;const char* names[]={"Chord root pitch","Chord start beat","Chord duration","Chord velocity"};const char* help[]={"Whole piano pitch 0-127. C3 = 48, C4 = 60. This is the root before inversion.","Zero-based beat inside the current pattern. The complete chord must fit.","Duration from 0.01 to 64 beats. The complete chord must fit inside this pattern.","Velocity from 1 to 100 percent."};auto* dialog=new AlertWindow(names[parameter],help[parameter],MessageBoxIconType::NoIcon,this);double value=parameter==0?chordOptions.root:parameter==1?chordOptions.beat:parameter==2?chordOptions.length:chordOptions.velocity*100;dialog->addTextEditor("value",String(value,parameter==0?0:4));dialog->addButton("Preview",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);auto expected=revision,serial=harmonyToolSerial;
    dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,parameter,expected,serial](int result){if(!safe||result!=1)return;auto text=dialog->getTextEditorContents("value").trim();auto* begin=text.toRawUTF8();char* end=nullptr;double value=std::strtod(begin,&end);if(text.isEmpty()||end==begin||*end!='\0'||!std::isfinite(value)){safe->status="Enter a finite numeric chord value.";return;}safe->acceptHarmonyNumber(parameter,value,expected,serial);}),true);
}
