        button(g,"Root: "+pitchLabel(chordOptions.root)+" ("+String(chordOptions.root)+")",{x,y+204,col,28},harmonyNumber,0);button(g,"Beat: "+String(chordOptions.beat,3),{x+col+8,y+204,col,28},harmonyNumber,1);button(g,"Length: "+String(chordOptions.length,3),{x+2*(col+8),y+204,col,28},harmonyNumber,2);
