bool Studio::performHarmonyAction(int action,int data){
    if(action==progressionOpen||action==progressionSettings||action==progressionExamples){if(recording||recorder.isActive()){status="Finish the take before using progressions.";return true;}if(action==progressionOpen)openNoteTools(NoteToolMode::buildProgression);else if(action==progressionSettings)showProgressionSettings(data==1);else showProgressionExamples();return true;}
    if(action<harmonySettingsOpen||action>harmonySkip)return false;if(recording||recorder.isActive()){status="Finish the take before using harmony tools.";return true;}
    if(action==harmonySettingsOpen){showHarmonySettings();return true;}if(action==harmonyFitOpen||action==harmonyChordOpen){openNoteTools(action==harmonyFitOpen?NoteToolMode::fitScale:NoteToolMode::buildChord);return true;}
    if(!harmonyContext(revision,harmonyToolSerial)){status="Use current selection/channel to start a harmony preview.";return true;}if(action==harmonyChoice)showHarmonyChoice(data);else if(action==harmonyNumber)editHarmonyNumber(data);else if(action==harmonyDirection)acceptHarmonyChoice(3,data,revision,harmonyToolSerial);else if(action==harmonySkip){chordOptions.skipExact=!chordOptions.skipExact;++harmonyToolSerial;refreshNoteToolPreview();}return true;
}
